# ImageMagick installation path
$imagemagickPath = "C:\Program Files\ImageMagick-7.1.1-Q16-HDRI\magick.exe"

# Check if ImageMagick exists at the specified path
if (-not (Test-Path $imagemagickPath)) {
    Write-Host "ImageMagick not found at: $imagemagickPath"
    Write-Host "Please verify the installation path or install ImageMagick from: https://imagemagick.org/script/download.php"
    exit 1
}

$sizes = @(
    @{name="icon-19.png"; size=19},
    @{name="icon-38.png"; size=38},
    @{name="icon-48.png"; size=48},
    @{name="icon-96.png"; size=96}
)

Write-Host "Starting icon conversion..."
Write-Host "Current directory: $PWD"

foreach ($size in $sizes) {
    & $imagemagickPath convert -background none -resize "$($size.size)x$($size.size)" icon.svg $size.name
    if ($LASTEXITCODE -eq 0) {
        Write-Host "Created $($size.name) successfully"
    } else {
        Write-Host "Failed to create $($size.name)"
        exit 1
    }
}

Write-Host "Icon conversion complete!"

js/content.js.content:
// Initialize extension state
let isEnabled = true;
let highlightedWords = new Set();

// Function to create tooltip element
function createTooltip(word, meaning) {
    const tooltip = document.createElement('div');
    tooltip.className = 'gre-tooltip';
    tooltip.textContent = meaning;
    tooltip.style.position = 'absolute';
    tooltip.style.zIndex = '10000';
    tooltip.style.backgroundColor = 'white';
    tooltip.style.border = '1px solid #ccc';
    tooltip.style.padding = '5px';
    tooltip.style.borderRadius = '3px';
    tooltip.style.boxShadow = '0 2px 5px rgba(0,0,0,0.2)';
    tooltip.style.maxWidth = '300px';
    tooltip.style.wordWrap = 'break-word';
    return tooltip;
}

// Function to highlight words
function highlightWords() {
    if (!isEnabled) return;

    const textNodes = document.evaluate(
        "//text()[not(ancestor::script) and not(ancestor::style)]",
        document.body,
        null,
        XPathResult.UNORDERED_NODE_SNAPSHOT_TYPE,
        null
    );

    for (let i = 0; i < textNodes.snapshotLength; i++) {
        const node = textNodes.snapshotItem(i);
        const text = node.textContent;
        const words = text.split(/\b/);

        let newHTML = '';
        for (const word of words) {
            const lowerWord = word.toLowerCase();
            if (greWordList[lowerWord] && !highlightedWords.has(word)) {
                highlightedWords.add(word);
                newHTML += `<span class="gre-highlight" data-word="${word}" data-meaning="${greWordList[lowerWord]}">${word}</span>`;
            } else {
                newHTML += word;
            }
        }

        if (newHTML !== text) {
            const span = document.createElement('span');
            span.innerHTML = newHTML;
            node.parentNode.replaceChild(span, node);
        }
    }
}

// Function to handle tooltip events
function handleTooltipEvents() {
    document.addEventListener('mouseover', (e) => {
        if (e.target.classList.contains('gre-highlight')) {
            const word = e.target.dataset.word;
            const meaning = e.target.dataset.meaning;
            if (meaning) {
                const tooltip = createTooltip(word, meaning);
                document.body.appendChild(tooltip);

                const rect = e.target.getBoundingClientRect();
                tooltip.style.left = `${rect.left + window.scrollX}px`;
                tooltip.style.top = `${rect.bottom + window.scrollY + 5}px`;

                e.target.addEventListener('mouseout', () => {
                    tooltip.remove();
                }, { once: true });
            }
        }
    });
}

// Initialize extension
function initialize() {
    // Load extension state from storage
    browser.storage.local.get('isEnabled', (result) => {
        isEnabled = result.isEnabled !== undefined ? result.isEnabled : true;
        if (isEnabled) {
            highlightWords();
            handleTooltipEvents();
        }
    });

    // Listen for state changes from popup
    browser.runtime.onMessage.addListener((message) => {
        if (message.type === 'toggle') {
            isEnabled = message.isEnabled;
            if (isEnabled) {
                highlightWords();
                handleTooltipEvents();
            } else {
                // Remove highlights
                document.querySelectorAll('.gre-highlight').forEach(el => {
                    el.replaceWith(el.textContent);
                });
                highlightedWords.clear();
            }
        } else if (message.type === 'getWordCount') {
            return Promise.resolve({ count: highlightedWords.size });
        }
    });
}

// Start initialization
initialize();

// Handle dynamic content changes
const observer = new MutationObserver((mutations) => {
    if (isEnabled) {
        highlightWords();
    }
});

observer.observe(document.body, {
    childList: true,
    subtree: true,
    characterData: true
});

popup/popup.js.content:
// Initialize popup
document.addEventListener('DOMContentLoaded', () => {
    const toggle = document.getElementById('toggle');
    const wordCount = document.getElementById('wordCount');

    // Load initial state
    browser.storage.local.get('isEnabled', (result) => {
        toggle.checked = result.isEnabled !== undefined ? result.isEnabled : true;
    });

    // Update word count
    function updateWordCount() {
        browser.tabs.query({ active: true, currentWindow: true }, (tabs) => {
            browser.tabs.sendMessage(tabs[0].id, { type: 'getWordCount' })
                .then(response => {
                    wordCount.textContent = `Words found: ${response.count}`;
                })
                .catch(() => {
                    wordCount.textContent = 'Words found: 0';
                });
        });
    }

    // Handle toggle changes
    toggle.addEventListener('change', () => {
        const isEnabled = toggle.checked;
        browser.storage.local.set({ isEnabled });

        browser.tabs.query({ active: true, currentWindow: true }, (tabs) => {
            browser.tabs.sendMessage(tabs[0].id, {
                type: 'toggle',
                isEnabled
            });
        });
    });

    // Update word count periodically
    updateWordCount();
    setInterval(updateWordCount, 1000);
});

